const items = $input.all();
const trim = (v) => (typeof v === "string" ? v.trim() : (v == null ? "" : String(v)));
return items.map((item) => {
  const b = item.json.body || item.json;
  const first = trim(b.first_name);
  const last = trim(b.last_name);
  const email = trim(b.email).toLowerCase();
  const phoneDigits = trim(b.phone).replace(/[^0-9+]/g, "");
  const nowIso = new Date().toISOString();
  const leadId = "zhorx_" + Date.now().toString(36) + "_" + Math.random().toString(36).slice(2, 8);
  return { json: {
    first_name: first,
    last_name: last,
    full_name: (first + " " + last).trim(),
    email,
    phone: phoneDigits,
    company: trim(b.company),
    industry: trim(b.industry),
    website: trim(b.website),
    company_size: trim(b.company_size),
    monthly_leads: trim(b.monthly_leads),
    problem: trim(b.problem),
    automation_needed: trim(b.automation_needed),
    preferred_meeting_time: trim(b.preferred_meeting_time),
    source: "Zhorx Website",
    original_source: trim(b.source),
    lead_id: leadId,
    created_at: nowIso,
  } };
});

