return $input.all().map((item) => {
  const ev = item.json;
  const attendees = Array.isArray(ev.attendees) ? ev.attendees : [];
  const guest = attendees.find((a) => a && a.email && !a.self) || attendees[0] || {};
  const email = (guest.email || (ev.creator && ev.creator.email) || "").toLowerCase();
  const start = (ev.start && (ev.start.dateTime || ev.start.date)) || "";
  return { json: {
    email,
    meeting_time: start,
    event_id: ev.id || "",
    summary: ev.summary || "",
  } };
});

