return $input.all().map((item) => {
  const from = item.json.from || "";
  const match = from.match(/<([^>]+)>/);
  const email = (match ? match[1] : from).trim().toLowerCase();
  return { json: {
    email,
    subject: item.json.subject || "",
    snippet: item.json.snippet || "",
    thread_id: item.json.threadId || "",
  } };
});

